package com.ruoyi.medical.persistence;
import com.ruoyi.medical.identity.*;
import com.ruoyi.medical.persistence.mapper.*;
import java.nio.file.*;
import java.nio.file.attribute.*;
import java.time.Duration;
import java.util.*;
import javax.sql.DataSource;
import org.springframework.beans.factory.annotation.*;
import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;
import org.springframework.context.annotation.*;
@Configuration(proxyBeanMethods=false)
@ConditionalOnProperty(prefix="medical.formal-evaluation-execution",name="enabled",havingValue="true",matchIfMissing=false)
public class FormalEvaluationRuntimeConfiguration {
 @Bean FormalEvaluationRuntimeSchema formalEvaluationRuntimeSchema()throws Exception{return new FormalEvaluationRuntimeSchema();}
 @Bean FormalEvaluationDeployments formalEvaluationDeployments(@Value("${medical.formal-evaluation-execution.deployments-file}")Path file,@Value("${medical.formal-evaluation-execution.deployments-owner}")String owner,@Value("${medical.formal-evaluation-execution.deployments-sha256}")String hash)throws Exception {
  if(!file.isAbsolute()||!file.normalize().equals(file)||!file.toRealPath().equals(file)||owner.isBlank())throw new IllegalArgumentException("OWNED_EVAL_DEPLOYMENTS_REQUIRED");var principal=file.getFileSystem().getUserPrincipalLookupService().lookupPrincipalByName(owner);
  var before=Files.readAttributes(file,BasicFileAttributes.class,LinkOption.NOFOLLOW_LINKS);if(!before.isRegularFile()||before.size()<1||before.size()>2097152||!Files.getOwner(file,LinkOption.NOFOLLOW_LINKS).equals(principal)||!Set.of(PosixFilePermissions.fromString("r--------"),PosixFilePermissions.fromString("rw-------")).contains(Files.getPosixFilePermissions(file,LinkOption.NOFOLLOW_LINKS)))throw new IllegalArgumentException("PRIVATE_EVAL_DEPLOYMENTS_REQUIRED");
  byte[] bytes;try(var in=Files.newInputStream(file,LinkOption.NOFOLLOW_LINKS)){bytes=in.readNBytes(2097153);}var after=Files.readAttributes(file,BasicFileAttributes.class,LinkOption.NOFOLLOW_LINKS);if(bytes.length!=before.size()||!Objects.equals(before.fileKey(),after.fileKey())||!before.lastModifiedTime().equals(after.lastModifiedTime())||before.size()!=after.size())throw new IllegalArgumentException("EVAL_DEPLOYMENTS_CHANGED");
  var parser=com.fasterxml.jackson.databind.json.JsonMapper.builder().enable(com.fasterxml.jackson.core.StreamReadFeature.STRICT_DUPLICATE_DETECTION).enable(com.fasterxml.jackson.databind.DeserializationFeature.FAIL_ON_TRAILING_TOKENS).build();return new FormalEvaluationDeployments(parser.readTree(bytes),hash);
 }
 @Bean FormalEvaluationControlAccess formalEvaluationControlAccess(DataSource data,TenantTransaction tx,@Qualifier("formalRunServiceIdentity")ServiceCertificateIdentity identities,PermissionMapper permissions,PermissionAuthority grants,RunTokenAuthoritySchema schema,FormalEvaluationJobs jobs,@Value("${medical.formal-evaluation-execution.read-timeout-seconds:300}")long seconds){return new FormalEvaluationControlAccess(data,tx,identities,permissions,grants,schema,jobs,Duration.ofSeconds(seconds));}
 @Bean FormalEvaluationNodeLeases formalEvaluationNodeLeases(DataSource data,FormalEvaluationJobs jobs,FormalEvaluationLaunchLedger launches,PermissionSchema json,@Value("${medical.formal-evaluation-execution.lease-seconds:300}")long seconds){return new FormalEvaluationNodeLeases(data,jobs,launches,json,Duration.ofSeconds(seconds));}
 @Bean FormalEvaluationContextReads formalEvaluationContextReads(DataSource data,PermissionSchema json,FormalEvaluationJobs jobs,FormalEvaluationInputService inputs,FormalEvaluationContextStore contexts,FormalEvaluationContextPackages packages,FormalCapabilityIdentityAuthority capabilities,FormalRuntimeCapabilityIdentityAuthority components,AgentExecutionPolicyAuthority policies,ScopeSnapshotStore scopes,DependencyLineage lineage,ArtifactRegistryMapper artifacts,SourceReadAuthority sources,TaskFieldSourceAuthority processing,SourceUploadTransport transport,EvaluationRuleAuthority rules,RunTokenAuthoritySchema roles,FormalAgentCandidateAuthority candidates){return new FormalEvaluationContextReads(data,json,jobs,inputs,contexts,packages,capabilities,components,policies,scopes,lineage,artifacts,sources,processing,transport,rules,roles,candidates);}
 @Bean FormalEvaluationSupervisor formalEvaluationSupervisor(DataSource data,PermissionSchema json,@Qualifier("formalEvaluationSupervisorTrust")ServiceCertificateIdentity.TrustSource trust,@Qualifier("formalEvaluationSupervisorTls")ServiceClientTlsStore.ContextSource tls){return new FormalEvaluationSupervisor(data,json,new ServiceCertificateIdentity(trust),trust,tls);}
 @Bean FormalEvaluationNodeRuntime formalEvaluationNodeRuntime(DataSource data,PermissionSchema json,FormalEvaluationNodeLeases leases,FormalEvaluationDeployments deployments,@Qualifier("formalRunServiceIdentity")ServiceCertificateIdentity identities,FormalEvaluationJobs jobs,FormalEvaluationLaunchLedger launches,FormalEvaluationNodeInputs inputs,FormalEvaluationRuntimeObjects objects,FormalEvaluationSupervisor supervisor,FormalEvaluationInvocationService invocations,FormalEvaluationNodeOutcomes outcomes,FormalEvaluationToolReceipts tools,org.springframework.beans.factory.ObjectProvider<FormalEvaluationDeterministicRuntime> deterministic){return new FormalEvaluationNodeRuntime(data,json,leases,deployments,identities,jobs,launches,inputs,objects,supervisor,invocations,outcomes,tools,deterministic);}
 @Bean FormalEvaluationSupervisorGate formalEvaluationSupervisorGate(DataSource data,FormalEvaluationControlAccess controls,FormalEvaluationDeployments deployments,FormalEvaluationContextReads contexts,PermissionSchema json){return new FormalEvaluationSupervisorGate(data,controls,deployments,contexts,json);}
 @Bean FormalEvaluationCellCompletion formalEvaluationCellCompletion(DataSource data,PermissionSchema json,FormalEvaluationJobs jobs,FormalEvaluationLaunchLedger launches,FormalEvaluationNodeRuntime runtime,FormalEvaluationCompletionService completions,FormalEvaluationInvocationService invocations){return new FormalEvaluationCellCompletion(data,json,jobs,launches,runtime,completions,invocations);}
 @Bean FormalEvaluationRuntimeService formalEvaluationRuntimeService(DataSource data,FormalEvaluationControlAccess access,FormalEvaluationNodeInputs inputs,FormalEvaluationNodeLeases leases,FormalEvaluationNodeRuntime runtime,FormalEvaluationSupervisor supervisor,FormalEvaluationRuntimeObjects objects,@Qualifier("formalEvaluationRuntimeTransport")RuntimeObjectTransport transport,FormalEvaluationNodeOutcomes outcomes,FormalEvaluationInvocationService invocations,FormalEvaluationCompletionService completions,FormalEvaluationJobs jobs,FormalEvaluationLaunchLedger launches,PermissionSchema json,FormalEvaluationStageInputPreparation stages,FormalEvaluationCellCompletion cells,FormalInvocationCancellation cancellation,FormalEvaluationDeployments deployments,FormalEvaluationDeterministicRuntime deterministic,FormalEvaluationDeterministicObjects deterministicObjects){return new FormalEvaluationRuntimeService(data,access,inputs,leases,runtime,supervisor,objects,transport,outcomes,invocations,completions,jobs,launches,json,stages,cells,cancellation,deployments,deterministic,deterministicObjects);}
}
